ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  kind: "task",
  id: vars.a2aTaskId,
  contextId: vars.a2aContextId,
  status: {
    state: "completed",
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"},
    message: {
      kind: "message",
      role: "agent",
      messageId: uuid(),
      taskId: vars.a2aTaskId,
      contextId: vars.a2aContextId,
      parts: [ { kind: "text", text: payload.response } ]
    }
  },
  artifacts: [
    {
      artifactId: uuid(),
      name: "similar-cases",
      parts: [ { kind: "text", text: payload.response } ]
    }
  ],
  metadata: {}
}
